package com.aaliyun.leadnews.article.domain;import com.aaliyun.leadnews.common.persistence.BaseEntity;import com.baomidou.mybatisplus.annotation.*;@TableName("ap_channel") public class Channel extends BaseEntity {@TableId(type=IdType.AUTO)private Long id;private String name;private String description;private String status;private Integer ord;public Long getId(){return id;}public void setId(Long v){id=v;}public String getName(){return name;}public void setName(String v){name=v;}public String getDescription(){return description;}public void setDescription(String v){description=v;}public String getStatus(){return status;}public void setStatus(String v){status=v;}public Integer getOrd(){return ord;}public void setOrd(Integer v){ord=v;}}
